    ALTS_FROM_WHEN  = "Von %s, %s",
    ALTS_GOT_ASK    = "Clara Combo Points: Dieser neue Charakter hat die Spieleinstellungen des Profils „%s“ erhalten (Aktionsleisten, Spieloptionen, Layout des Bearbeitungsmodus).\n\nInterface neu laden, um abzuschließen?",
